mapper.select:


    d.del_flag = '0'
     AND d.dispatch_no LIKE CONCAT('%', #{dispatchNo}, '%')
     AND d.work_order_id = #{workOrderId}
     AND d.work_order_no LIKE CONCAT('%', #{workOrderNo}, '%')
     AND d.op_seq = #{opSeq}
     AND d.process_name LIKE CONCAT('%', #{processName}, '%')
     AND d.resource_name LIKE CONCAT('%', #{resourceName}, '%')
     AND d.team_name LIKE CONCAT('%', #{teamName}, '%')
     AND d.team_id = #{teamId}
     AND d.status = #{status}
     AND date(d.create_time) >= #{params.beginTime}
     AND date(d.create_time) <= #{params.endTime}

ORDER BY d.dispatch_id DESC
